    // MARK: - Dispatch

    static func drawHeroLegs(_ build: BodyBuild, _ ctx: CGContext, _ ink: HeroInk) {
        switch build {
        case .lithe: heroLegsLithe(ctx, ink)
        case .standard: heroLegsStandard(ctx, ink)
        case .broad: heroLegsBroad(ctx, ink)
        case .stout: heroLegsStout(ctx, ink)
        case .towering: heroLegsTowering(ctx, ink)
        }
    }

    static func drawHeroCloak(_ style: CloakStyle, _ build: BodyBuild, _ ctx: CGContext, _ ink: HeroInk) {
        switch (style, build) {
        case (.hooded, .lithe): heroCloakHoodedLithe(ctx, ink)
        case (.hooded, .standard): heroCloakHoodedStandard(ctx, ink)
        case (.hooded, .broad): heroCloakHoodedBroad(ctx, ink)
        case (.hooded, .stout): heroCloakHoodedStout(ctx, ink)
        case (.hooded, .towering): heroCloakHoodedTowering(ctx, ink)
        case (.mantle, .lithe): heroCloakMantleLithe(ctx, ink)
        case (.mantle, .standard): heroCloakMantleStandard(ctx, ink)
        case (.mantle, .broad): heroCloakMantleBroad(ctx, ink)
        case (.mantle, .stout): heroCloakMantleStout(ctx, ink)
        case (.mantle, .towering): heroCloakMantleTowering(ctx, ink)
        case (.longCoat, .lithe): heroCloakLongCoatLithe(ctx, ink)
        case (.longCoat, .standard): heroCloakLongCoatStandard(ctx, ink)
        case (.longCoat, .broad): heroCloakLongCoatBroad(ctx, ink)
        case (.longCoat, .stout): heroCloakLongCoatStout(ctx, ink)
        case (.longCoat, .towering): heroCloakLongCoatTowering(ctx, ink)
        case (.shroud, .lithe): heroCloakShroudLithe(ctx, ink)
        case (.shroud, .standard): heroCloakShroudStandard(ctx, ink)
        case (.shroud, .broad): heroCloakShroudBroad(ctx, ink)
        case (.shroud, .stout): heroCloakShroudStout(ctx, ink)
        case (.shroud, .towering): heroCloakShroudTowering(ctx, ink)
        case (.pilgrim, .lithe): heroCloakPilgrimLithe(ctx, ink)
        case (.pilgrim, .standard): heroCloakPilgrimStandard(ctx, ink)
        case (.pilgrim, .broad): heroCloakPilgrimBroad(ctx, ink)
        case (.pilgrim, .stout): heroCloakPilgrimStout(ctx, ink)
        case (.pilgrim, .towering): heroCloakPilgrimTowering(ctx, ink)
        case (.vampire, .lithe): heroCloakVampireLithe(ctx, ink)
        case (.vampire, .standard): heroCloakVampireStandard(ctx, ink)
        case (.vampire, .broad): heroCloakVampireBroad(ctx, ink)
        case (.vampire, .stout): heroCloakVampireStout(ctx, ink)
        case (.vampire, .towering): heroCloakVampireTowering(ctx, ink)
        case (.wizard, .lithe): heroCloakWizardLithe(ctx, ink)
